-- TripSense database schema
--
-- This file is DOCUMENTATION, not a migration script. Nothing runs it.
-- The real schema is generated by Hibernate from the @Entity classes in
-- src/main/java/csd/tripsense/ when the application starts.
--
-- Keep it in step: if a pull request adds or changes an entity, it updates
-- this file in the same commit. A schema file that has drifted from the code
-- is worse than no schema file at all.
--
-- To see the schema the database actually has:
--     sqlite3 data/tripsense.db ".schema"


create table user {
    id integer primary key,
    username varchar not null unique,
    email varchar not null unique,
    password varchar not null,
    role varchar not null,
    enabled boolean            -- null counts as enabled
}

create table country {
    id integer primary key,
    name varchar not null
    fips_code varchar
}

create table itinerary {
    id integer primary key,
    user_id integer not null,
    country_id integer not null,
    name varchar,
    date_start timestamp,
    date_end timestamp,

    foreign key (user_id) references user(id),
    foreign key (country_id) references country(id)
}


create table activity {
    id integer primary key,
    itinerary_id integer not null,
    country_id integer,            -- copied from the itinerary; null on rows created before this column existed
    name varchar not null,
    address varchar,
    date_start timestamp,
    date_end timestamp,
    category varchar,          -- ActivityCategory, null on rows made before it existed

    foreign key (itinerary_id) references itinerary(id),
    foreign key (country_id) references country(id)
}

-- News table for transit disruption updates and news articles.
-- Corresponds to the News entity in csd/tripsense/news/News.java
CREATE TABLE IF NOT EXISTS news (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    description TEXT,
    source TEXT,
    url TEXT,
    published_at TIMESTAMP
);

create table impact {
    id integer primary key,
    user_id integer not null,
    news_id integer not null,
    itinerary_id integer,
    activity_id integer,
    impacted boolean,
    reason varchar(500),
    rejected boolean,

    foreign key (user_id) references user(id),
    foreign key (news_id) references news(id),
    foreign key (itinerary_id) references itinerary(id),
    foreign key (activity_id) references activity(id)
}

-- Places a traveller could go instead when an activity is disrupted.
-- Generated worldwide by tools/build-options.py and seeded from options.sql, so the
-- model picks from real rows instead of inventing a venue. Id is the Wikidata Q number.
create table activity_option {
    id integer primary key,
    country varchar not null,
    area varchar not null,       -- a word that shows up in activity addresses, eg "Sapporo"
    category varchar not null,
    name varchar not null,
    address varchar,
    latitude double,             -- null on the first rows, generated before we kept these
    longitude double
}

create index idx_activity_option_country on activity_option(country);

create table recommendation {
    id integer primary key,
    impact_id integer not null,
    severity varchar not null,          -- HIGH, MEDIUM, LOW
    action varchar not null,            -- REPLACE, RELOCATE, RESCHEDULE, MONITOR, CANCEL
    advice varchar(500),
    suggested_option_id integer,        -- null when there is nothing to swap to
    created_at timestamp,

    foreign key (impact_id) references impact(id),
    foreign key (suggested_option_id) references activity_option(id)

CREATE TABLE user_preference (
    id                        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id                   BIGINT NOT NULL UNIQUE REFERENCES "user"(id) ON DELETE CASCADE,
    risk_tolerance            VARCHAR(20)  NOT NULL DEFAULT 'MEDIUM',
    flexibility_level         VARCHAR(30)  NOT NULL DEFAULT 'SOMEWHAT_FLEXIBLE',
    explanation_detail        VARCHAR(20)  NOT NULL DEFAULT 'BRIEF',
    travel_group              VARCHAR(20)  NOT NULL DEFAULT 'SOLO',
    travelling_with_children  BOOLEAN      NOT NULL DEFAULT FALSE,
    travelling_with_elderly   BOOLEAN      NOT NULL DEFAULT FALSE,
    updated_at                TIMESTAMP    NOT NULL
);
-- Which countries a news article is about. Corresponds to News.countries.
create table news_country {
    news_id integer not null,
    country_id integer not null,

    primary key (news_id, country_id),
    foreign key (news_id) references news(id),
    foreign key (country_id) references country(id)
}
